// 处理工具选项面板（DataForm）字段变化，更新参数字典并同步状态栏摘要。
export default function applyToolOption(state, args) {
  const fieldName = String(args?.name ?? "");
  const fieldVal = args?.value ?? null;
  const hook = String(args?.hook ?? fieldName);
  const prevValues = state.toolOptions?.values ?? {};
  const nextValues = Object.assign({}, prevValues);
  if (fieldName) {
    nextValues[fieldName] = fieldVal;
  }
  return {
    "toolOptions.values": nextValues,
    "toolOptions.lastHook": hook,
    "project.statusMessage": "工具参数更新：" + fieldName + " = " + String(fieldVal),
  };
}

functions.manageLayerGroup:
// 处理图层面板中的图层分组操作（解组保留图层、删除分组及成员、素材转图层）。
export default function manageLayerGroup(state, args) {
  const mode = String(args?.mode ?? "");
  const rawItems = Array.isArray(state.layers?.items) ? state.layers.items.slice() : [];
  const sel = Number(state.layers?.selectedIndex ?? 0);
  const nextId = Number(state.layers?.nextId ?? rawItems.length + 1);

  if (mode === "assetToLayer") {
    const assets = Array.isArray(state.assets?.items) ? state.assets.items : [];
    const assetIdx = Number(state.assets?.selectedIndex ?? 0);
    const asset = assets[assetIdx] ?? assets[0] ?? { id: 1, name: "默认素材.png" };
    const newLayer = {
      id: "lyr_asset_" + nextId,
      name: "素材层：" + String(asset.name ?? "素材"),
      kind: "Asset",
      isGroup: false,
      depth: 0,
      collapsed: false,
      checked: true,
      visible: true,
      locked: false,
    };
    rawItems.push(newLayer);
    return {
      "layers.items": rawItems,
      "layers.selectedIndex": rawItems.length - 1,
      "layers.nextId": nextId + 1,
      "project.statusMessage": "已将素材转为图层：" + newLayer.name,
    };
  }

  let groupIdx = -1;
  if (sel >= 0 && sel < rawItems.length && rawItems[sel]?.isGroup) {
    groupIdx = sel;
  } else if (sel >= 0 && sel < rawItems.length && Number(rawItems[sel]?.depth ?? 0) > 0) {
    for (let i = sel - 1; i >= 0; i--) {
      if (rawItems[i]?.isGroup) {
        groupIdx = i;
        break;
      }
    }
  }
  if (groupIdx < 0) {
    groupIdx = rawItems.findIndex((it) => Boolean(it?.isGroup));
  }
  if (groupIdx < 0) {
    return {
      "project.statusMessage": "当前没有可操作的图层组",
    };
  }

  const groupDepth = Number(rawItems[groupIdx]?.depth ?? 0);
  const groupName = String(rawItems[groupIdx]?.name ?? "图层组");
  let endChildIdx = groupIdx + 1;
  while (endChildIdx < rawItems.length && Number(rawItems[endChildIdx]?.depth ?? 0) > groupDepth) {
    endChildIdx++;
  }

  if (mode === "dissolve") {
    const updated = [];
    for (let i = 0; i < rawItems.length; i++) {
      if (i === groupIdx) continue;
      const item = Object.assign({}, rawItems[i]);
      if (i > groupIdx && i < endChildIdx) {
        item.depth = Math.max(0, Number(item.depth ?? 1) - 1);
      }
      updated.push(item);
    }
    const nextSel = Math.min(groupIdx, Math.max(0, updated.length - 1));
    return {
      "layers.items": updated,
      "layers.selectedIndex": nextSel,
      "project.statusMessage": "已解组并保留成员图层：" + groupName,
    };
  }

  if (mode === "deleteGroup") {
    const updated = rawItems.filter((_, i) => i < groupIdx || i >= endChildIdx);
    if (updated.length === 0) {
      updated.push({
        id: "lyr_default",
        name: "默认背景层",
        kind: "Raster",
        isGroup: false,
        depth: 0,
        collapsed: false,
        checked: true,
        visible: true,
        locked: false,
      });
    }
    const nextSel = Math.min(groupIdx, Math.max(0, updated.length - 1));
    return {
      "layers.items": updated,
      "layers.selectedIndex": nextSel,
      "project.statusMessage": "已删除图层组及成员：" + groupName,
    };
  }

  return {};
}

functions.recordHistory:
// 记录一条新的历史操作步骤；若当前处于回退状态（mutedFrom >= 0），先截断被撤销的后续分支。
export default function recordHistory(state, args) {
  const rawItems = Array.isArray(state.history?.items) ? state.history.items : [];
  const mutedFrom = Number(state.history?.mutedFrom ?? -1);
  const nextId = Number(state.history?.nextId ?? rawItems.length + 1);
  const label = String(args?.label ?? "画布操作");
  const base = mutedFrom >= 0 && mutedFrom < rawItems.length ? rawItems.slice(0, mutedFrom) : rawItems.slice();
  base.push({
    id: nextId,
    name: label,
    badge: "#" + nextId,
  });
  return {
    "history.items": base,
    "history.selectedIndex": base.length - 1,
    "history.mutedFrom": -1,
    "history.nextId": nextId + 1,
  };
}

functions.rewindHistory:
// 在历史面板中执行撤销、重做或点击某条历史记录回溯，并同步 mutedFrom 置灰分界线。
export default function rewindHistory(state, args) {
  const items = Array.isArray(state.history?.items) ? state.history.items : [];
  if (items.length === 0) return {};
  const cur = Number(state.history?.selectedIndex ?? items.length - 1);
  const mode = String(args?.mode ?? "select");
  if (mode === "clear") {
    return {
      "history.items": [{ id: 1, name: "初始化画布 (1920x1080)", badge: "#1" }],
      "history.selectedIndex": 0,
      "history.mutedFrom": -1,
      "history.nextId": 2,
      "project.statusMessage": "已清空历史记录",
    };
  }
  let target = cur;
  if (mode === "undo") {
    target = Math.max(0, cur - 1);
  } else if (mode === "redo") {
    target = Math.min(items.length - 1, cur + 1);
  } else {
    const rawIdx = Number(args?.index ?? args?.value ?? cur);
    if (Number.isInteger(rawIdx) && rawIdx >= 0 && rawIdx < items.length) {
      target = rawIdx;
    }
  }
  const mutedFrom = target < items.length - 1 ? target + 1 : -1;
  const entryName = items[target]?.name ?? ("步骤 " + (target + 1));
  return {
    "history.selectedIndex": target,
    "history.mutedFrom": mutedFrom,
    "project.statusMessage": "历史回溯：" + entryName,
  };
}

functions.syncPresetDimensions:
// 根据新建项目对话框里选择的画幅预设，返回对应的画布宽高和帧率。
export default function syncPresetDimensions(state) {
  const preset = state.newProject?.preset ?? "1080p";
  if (preset === "720p") {
    return {
      "newProject.width": 1280,
      "newProject.height": 720,
      "newProject.fps": 24,
    };
  }
  if (preset === "Square") {
    return {
      "newProject.width": 1080,
      "newProject.height": 1080,
      "newProject.fps": 30,
    };
  }
  return {
    "newProject.width": 1920,
    "newProject.height": 1080,
    "newProject.fps": 24,
  };
}

